exports.getOrderHistory = async (userId) => {
  const orders = await db.getOrdersForUser(userId);
  const allProductIds = orders.flatMap(order => order.productIds);
  const products = await db.getProductsByIds(allProductIds);
  const productMap = new Map(products.map(p => [p.id, p]));
  return orders.map(order => ({
    ...order,
    items: order.productIds.map(id => productMap.get(id))
  }));
};

